package com.qrid.util;
import com.qrid.config.Database;import com.qrid.model.Identity;import javax.activation.DataHandler;import javax.mail.*;import javax.mail.internet.*;import javax.mail.util.ByteArrayDataSource;import java.util.Properties;
public class EmailService{
 public boolean sendIdentityCard(String to,Identity identity,byte[] pdf)throws Exception{if(!Boolean.parseBoolean(Database.property("smtp.enabled")))return false;Properties p=new Properties();p.put("mail.smtp.host",Database.property("smtp.host"));p.put("mail.smtp.port",Database.property("smtp.port"));p.put("mail.smtp.auth","true");p.put("mail.smtp.starttls.enable",Database.property("smtp.starttls"));String user=Database.property("smtp.username"),password=Database.property("smtp.password");Session session=Session.getInstance(p,new Authenticator(){protected PasswordAuthentication getPasswordAuthentication(){return new PasswordAuthentication(user,password);}});MimeMessage message=new MimeMessage(session);message.setFrom(new InternetAddress(Database.property("smtp.from")));message.setRecipients(Message.RecipientType.TO,InternetAddress.parse(to));message.setSubject("Your QRID Campus Digital Identity");MimeBodyPart text=new MimeBodyPart();text.setText("Dear "+identity.getFullName()+",\n\nYour secure digital identity is attached. Keep it private and report loss immediately.\n\nQRID Campus","UTF-8");MimeBodyPart attachment=new MimeBodyPart();attachment.setDataHandler(new DataHandler(new ByteArrayDataSource(pdf,"application/pdf")));attachment.setFileName("QRID-"+identity.getIdentityNo().replaceAll("[^A-Za-z0-9_-]","_")+".pdf");MimeMultipart content=new MimeMultipart();content.addBodyPart(text);content.addBodyPart(attachment);message.setContent(content);Transport.send(message);return true;}
}
